package com.example.litera.favorites.data.mapper

import com.example.litera.book.domain.model.Book
import com.example.litera.database.FavoriteBook

/** Database row (generated by SQLDelight) -> domain model. SQLite INTEGER is Long, so convert to Int. */
fun FavoriteBook.toBook(): Book =
    Book(
        id = id,
        title = title,
        imageUrl = image_url,
        authors = authors,
        description = description,
        languages = languages,
        firstPublishYear = first_publish_year,
        averageRating = average_rating,
        ratingCount = rating_count?.toInt(),
        numPages = num_pages?.toInt(),
        numEditions = num_editions.toInt()
    )
